div.script:
const canvas = document.getElementById('snowCanvas');
const ctx = canvas.getContext('2d');
const container = canvas.parentElement;
let flakes = [];
const numFlakes = 40;
let textBounds = null;

function measureText() {
  ctx.font = '900 5rem "Segoe UI"';
  const text = "Soon59";
  const metrics = ctx.measureText(text);
  textBounds = {
    x: canvas.width / 2 - metrics.width / 2,
    y: canvas.height / 2 - 40,
    width: metrics.width,
    height: 80
  };
}

function createFlakes() {
  flakes = [];
  for (let i = 0; i < numFlakes; i++) {
    flakes.push({
      x: Math.random() * canvas.width,
      // Position de départ invisible au-dessus du cadre
      y: Math.random() * -150 - 10,
      vx: (Math.random() - 0.5) * 0.8,
      vy: Math.random() * 1 + 0.6,
      fontSize: Math.random() * 15 + 15,
      alpha: Math.random() * 0.5 + 0.3,
      // Détermine si le flocon passe derrière ou devant le texte
      isBehind: Math.random() > 0.6
    });
  }
}

function animate() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  flakes.forEach(f => {
    f.x += f.vx;
    f.y += f.vy;

    if (!f.isBehind) {
      if (f.x > textBounds.x && f.x < textBounds.x + textBounds.width &&
          f.y > textBounds.y && f.y < textBounds.y + textBounds.height) {
          f.y = textBounds.y - 5;
          f.vy *= -0.5;
      }
    }

    if (f.y > canvas.height + 20) {
      f.y = Math.random() * -50 - 10;
      f.x = Math.random() * canvas.width;
      f.vy = Math.random() * 1 + 0.6;
    }

    ctx.font = f.fontSize + 'px Arial';
    ctx.fillStyle = 'rgba(255, 255, 255, ' + f.alpha + ')';
    ctx.fillText('❅', f.x, f.y);
  });
  requestAnimationFrame(animate);
}

canvas.width = 800;
canvas.height = 200;
measureText();
createFlakes();
animate();
